/**
 * `@melandlabs/workspace/postgres` — schema bootstrap.
 *
 * The Postgres backend mirrors the SQLite schema (`src/schema.ts`) table
 * for table so the two backends stay comparable and a workspace can be
 * moved between them without changing the host code. The differences
 * are the ones Postgres forces:
 *
 *   - ids are `INTEGER GENERATED BY DEFAULT AS IDENTITY` (int4, so
 *     node-postgres hands them back as plain numbers),
 *   - timestamps are `BIGINT` (unix seconds) — int8 comes back from
 *     node-postgres as a string, so the store casts them,
 *   - `metadata` / `provenance` are `JSONB` instead of JSON-in-TEXT,
 *   - the FTS5 mirror is replaced by a generated `tsvector` column.
 *
 * The generated column is the interesting one:
 *
 * ```sql
 * search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, index_text)) STORED
 * ```
 *
 * `index_text` holds the *derived* lexical text (the same
 * `workspaceIndexText()` output the SQLite backend feeds to FTS5), so
 * the two backends index the same tokens and a query that finds a
 * document in one finds it in the other.
 *
 * `to_tsvector(regconfig, text)` is immutable, which is what makes it
 * legal in a generated column. The configuration is passed explicitly —
 * the one-argument form is only `stable` and would be rejected.
 */

export const WORKSPACE_POSTGRES_SCHEMA_VERSION = 1;

/**
 * The workspace tables, in dependency order. Every statement is
 * idempotent, so `initialize()` can run on every boot.
 */
export const WORKSPACE_POSTGRES_DDL: string[] = [
	`CREATE TABLE IF NOT EXISTS workspace_resources (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    resource_type TEXT NOT NULL,
    canonical_key TEXT NOT NULL,
    title TEXT NOT NULL,
    storage_kind TEXT NOT NULL,
    current_version_id INTEGER,
    index_status TEXT NOT NULL DEFAULT 'pending',
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    metadata JSONB,
    UNIQUE (workspace_id, canonical_key)
  )`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_resources_workspace_type
    ON workspace_resources (workspace_id, resource_type)`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_resources_workspace_status
    ON workspace_resources (workspace_id, index_status)`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_resources_user
    ON workspace_resources (user_id)`,

	`CREATE TABLE IF NOT EXISTS workspace_resource_versions (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    resource_id INTEGER NOT NULL,
    version_number INTEGER NOT NULL,
    sha256 TEXT NOT NULL,
    change_kind TEXT NOT NULL,
    size_bytes INTEGER NOT NULL,
    parent_version_id INTEGER,
    source_path TEXT,
    created_at BIGINT NOT NULL,
    metadata JSONB,
    UNIQUE (resource_id, version_number)
  )`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_resource_versions_resource
    ON workspace_resource_versions (resource_id, version_number DESC)`,

	`CREATE TABLE IF NOT EXISTS workspace_chunks (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    chunk_id TEXT UNIQUE NOT NULL,
    resource_id INTEGER NOT NULL,
    version_id INTEGER NOT NULL,
    workspace_id TEXT NOT NULL,
    chunk_index INTEGER NOT NULL,
    chunk_count INTEGER NOT NULL,
    start_position INTEGER NOT NULL,
    end_position INTEGER NOT NULL,
    content TEXT NOT NULL,
    content_hash TEXT NOT NULL,
    embedding REAL[],
    embedding_model TEXT,
    embedding_dimensions INTEGER,
    embedding_updated_at BIGINT,
    index_text TEXT NOT NULL,
    search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, index_text)) STORED,
    UNIQUE (resource_id, version_id, chunk_index)
  )`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_chunks_workspace
    ON workspace_chunks (workspace_id)`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_chunks_resource
    ON workspace_chunks (resource_id, version_id)`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_chunks_search_vector
    ON workspace_chunks USING GIN (search_vector)`,

	`CREATE TABLE IF NOT EXISTS workspace_reference_edges (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id TEXT NOT NULL,
    source_resource_id INTEGER NOT NULL,
    source_version_id INTEGER,
    target_resource_id INTEGER NOT NULL,
    target_version_id INTEGER,
    edge_type TEXT NOT NULL,
    quote TEXT,
    provenance JSONB,
    created_at BIGINT NOT NULL,
    UNIQUE (workspace_id, source_resource_id, target_resource_id, edge_type)
  )`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_reference_edges_workspace
    ON workspace_reference_edges (workspace_id)`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_reference_edges_source
    ON workspace_reference_edges (source_resource_id)`,

	`CREATE TABLE IF NOT EXISTS workspace_jobs (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id TEXT NOT NULL,
    kind TEXT NOT NULL,
    status TEXT NOT NULL,
    total INTEGER NOT NULL DEFAULT 0,
    done INTEGER NOT NULL DEFAULT 0,
    error TEXT,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
  )`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_jobs_workspace
    ON workspace_jobs (workspace_id, created_at DESC)`,

	`CREATE TABLE IF NOT EXISTS workspace_resource_facts (
    workspace_id TEXT NOT NULL,
    resource_id INTEGER NOT NULL,
    version_id INTEGER NOT NULL,
    memory_fact_id TEXT NOT NULL,
    promoted_at BIGINT NOT NULL,
    promoted_by_run_id TEXT,
    PRIMARY KEY (workspace_id, resource_id, version_id, memory_fact_id)
  )`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_resource_facts_fact
    ON workspace_resource_facts (memory_fact_id)`,
	`CREATE INDEX IF NOT EXISTS idx_workspace_resource_facts_resource
    ON workspace_resource_facts (resource_id, version_id)`,
];

/**
 * The per-dimension vector table.
 *
 * The SQLite backend creates one `vec0` child table per embedding width
 * (`workspace_chunks_vec_d1536`); the Postgres backend does the same
 * with `pgvector`, so a workspace that switches embedding models keeps
 * both sets of vectors instead of overwriting them.
 *
 * The table name is derived from a validated integer — never from
 * user input — so it is safe to interpolate.
 */
export function workspaceVectorTableName(dimensions: number): string {
	if (!Number.isInteger(dimensions) || dimensions <= 0) {
		throw new Error(`Invalid workspace chunk embedding dimensions: ${dimensions}`);
	}
	return `workspace_chunks_vec_d${dimensions}`;
}

export function workspaceVectorTableDdl(dimensions: number): string[] {
	const table = workspaceVectorTableName(dimensions);
	return [
		`CREATE TABLE IF NOT EXISTS ${table} (
      chunk_id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL,
      embedding vector(${dimensions}) NOT NULL
    )`,
		`CREATE INDEX IF NOT EXISTS idx_${table}_workspace ON ${table} (workspace_id)`,
	];
}
